contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 betLimit, uint256 wagerAmount) public payable {
        require(msg.sender != address(0));
        require(wagerAmount == betLimit);
        require(address(this).balance >= wagerAmount);

        uint256 initialWinnersPot = c.winnersPot();
        bool initialOpen = c.hasPlayerWagered(address(this));

        bool reverted;
        try c.OpenToThePublic() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            c.wager{value: wagerAmount}();
            bool afterWager = c.hasPlayerWagered(address(this));
            uint256 afterWinnersPot = c.winnersPot();

            assert(
                afterWager == true &&
                afterWinnersPot == initialWinnersPot + wagerAmount &&
                c.currentBetLimit() == betLimit
            );
        } else {
            assert(
                initialWinnersPot == c.winnersPot() &&
                c.hasPlayerWagered(address(this)) == initialOpen
            );
        }
    }

    receive() external payable {}
}

