    }

    function run(uint256 wagerAmount) public payable {
        require(address(this).balance >= wagerAmount);
        require(wagerAmount == c.currentBetLimit());

        // This contract is the owner, but c starts closed, so a wager MUST fail before opening.
        bool wagerBeforeOpenReverted;
        try c.wager{value: wagerAmount}() {
            wagerBeforeOpenReverted = false;
        } catch {
            wagerBeforeOpenReverted = true;
        }

        c.OpenToThePublic();

        // Now that it is open, a valid wager by a fresh player must succeed.
        bool wagerAfterOpenReverted;
        try c.wager{value: wagerAmount}() {
            wagerAfterOpenReverted = false;
        } catch {
            wagerAfterOpenReverted = true;
        }
        bool playerWagered = c.hasPlayerWagered(address(this));
        uint256 balanceAfterWager = address(c).balance;

        assert(
            wagerBeforeOpenReverted &&
            !wagerAfterOpenReverted &&
            playerWagered &&
            balanceAfterWager >= wagerAmount
        );
    }

    receive() external payable {}
}

