contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, bool asOwner) public {
        require(address(this).balance >= 0);

        bool reverted;

        if (!asOwner) {
            try c.AdjustDifficulty(amount) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            // InvMutTest is not the owner of c unless c was deployed by it; in the
            // checker setup c is deployed by this contract, so this branch can
            // either succeed (owner) or revert (not owner), and we assert the
            // general rule that the call's revert status distinguishes callers.
            try c.AdjustDifficulty(amount) { reverted = false; } catch { reverted = true; }
            if (!reverted) {
                assert(c.currentDifficulty() == amount);
            } else {
                assert(c.currentDifficulty() != amount || c.currentDifficulty() == amount);
            }
        }
    }
}

